const listLokasi = `-- name: ListLokasi :many

SELECT l.id, l.entity_id, l.kode, l.nama, l.jenis, l.id_inv_gudang,
       l.id_lokasi_induk, l.status, l.version, l.created_at, l.updated_at,
       l.deleted_at,
       gr.nama AS nama_gudang,
       ir.nama AS nama_induk
FROM inv_lokasi_stok l
LEFT JOIN inv_gudang gr ON gr.id = l.id_inv_gudang
LEFT JOIN inv_lokasi_stok ir ON ir.id = l.id_lokasi_induk
WHERE l.deleted_at IS NULL
  AND ($1::text IS NULL OR l.jenis::text = $1::text)
  AND ($2::bigint IS NULL OR l.id_inv_gudang = $2::bigint)
  AND ($3::text IS NULL
       OR l.kode ILIKE '%' || $3::text || '%'
       OR l.nama ILIKE '%' || $3::text || '%')
  AND (
    ($4::boolean AND l.jenis::text <> 'INTERNAL')
    OR (
      NOT $4::boolean
      AND (
        $5::bigint[] IS NULL
        OR l.jenis::text <> 'INTERNAL'
        OR l.id_inv_gudang = ANY($5::bigint[])
      )
    )
  )
ORDER BY
  CASE WHEN $6 = '' THEN l.kode END ASC,
  CASE
    WHEN $6 = 'kode' AND NOT $7::boolean THEN l.kode
    WHEN $6 = 'nama' AND NOT $7::boolean THEN l.nama
  END ASC NULLS LAST,
  CASE
    WHEN $6 = 'kode' AND $7::boolean THEN l.kode
    WHEN $6 = 'nama' AND $7::boolean THEN l.nama
  END DESC NULLS FIRST,
  CASE
    WHEN $6 = 'created_at' AND NOT $7::boolean THEN l.created_at
    WHEN $6 = 'updated_at' AND NOT $7::boolean THEN l.updated_at
  END ASC NULLS LAST,
  CASE
    WHEN $6 = 'created_at' AND $7::boolean THEN l.created_at
    WHEN $6 = 'updated_at' AND $7::boolean THEN l.updated_at
  END DESC NULLS FIRST
LIMIT $9::int OFFSET $8::int
`

