const saldoLokasi = `-- name: SaldoLokasi :one
SELECT COALESCE(SUM(s.qty_on_hand), 0)::int AS n
FROM inv_saldo_stok s
WHERE s.id_inv_lokasi_stok = $1::bigint AND s.deleted_at IS NULL
`

// Total saldo on-hand lokasi (guard hapus INV-014 — COALESCE SUM, hidup).
func (q *Queries) SaldoLokasi(ctx context.Context, id int64) (int32, error) {
	row := q.db.QueryRow(ctx, saldoLokasi, id)
	var n int32
	err := row.Scan(&n)
	return n, err
}

